"""
    Calculate the CPU percentage for a process running in a particular
    scenario.

    :param results: Results to extract values from.
    :param process: Process name to calculate CPU usage for.
    """
def cpu_usage_for_process(results: Any, process: Any) -> object {
    process_results = [
        r
        for r in results
        if ((r['metric']['type'] == 'cputime') and (r['process'] == process))
    ];
    cpu_values = sum(r['value'] for r in process_results);
    wallclock_values = sum(r['wallclock'] for r in process_results);
    if (wallclock_values > 0) {
        return (float(cpu_values) / wallclock_values);
    }
    return None;
}

"""
    Calculates the distance traveled given the initial velocity, acceleration, and time, Helper function to the distance
    function.

    :param initial_velocity: Integer initial velocity
    :param acceleration: Integer acceleration
    :param time: Integer time

    :return: Integer distance traveled
    """
def distance_helper(initial_velocity: Any, acceleration: Any, time: Any) -> object {
    dist = (initial_velocity * time) + (0.5 * (acceleration * (time ** 2)));
    return dist;
}

