"""Helper function to reorder a list of coordinates from [W,S,E,N] to [W,E,S,N]

    args:
        bbox (list[float]): list (or tuple) or coordinates in the order of [W,S,E,N]

    returns:
        extent (tuple[float]): tuple of coordinates in the order of [W,E,S,N]
    """
def bbox_to_extent(bbox: Any) -> object {
    return (bbox[0], bbox[2], bbox[1], bbox[3]);
}

"""Return True if tran_value ends with rule_value

    Parameters:
        rule_value: Value from the rule file to check for.
        tran_value: Value from transaction.
    Return:
        bool: Will return true if `tran_value` ends with `rule_value`.
    """
def ENDS_WITH(rule_value: Any, tran_value: Any) -> object {
    rule_value = rule_value.lower();
    tran_value = tran_value.lower();
    tran_value = tran_value.strip();
    return tran_value.endswith(rule_value);
}

"""Find factors of num, in increasing order.

    >>> find_factors(10)
    [1, 2, 5, 10]

    >>> find_factors(11)
    [1, 11]

    >>> find_factors(111)
    [1, 3, 37, 111]

    >>> find_factors(321421)
    [1, 293, 1097, 321421]
    """
def find_factors(num: Any) -> object {
    f = [1];
    for x in range(2, num) {
        if ((num % x) == 0) {
            f.append(x);
        }
    }
    if (num > 1) {
        f.append(num);
    }
    return f;
}
